// DenaivamBulwark — walls off the enemy's side of the map center and masses the army there.
// Units never attack the enemy base: they guard the center, the wall and our own base.
// Soldiers fight with the soldier combat micro (focus fire, first strike, dodge steps).
// Plan: from tick 60 a worker builds an arc of walls 4 tiles from the center, facing the
// enemy, so enemies cannot walk straight in and must go around. The wall then gets thicker
// (lines at 5 and 6 tiles), destroyed walls are rebuilt, and spare energy upgrades them.
// Soldiers and guard scouts stay massed in the center behind it; crystal raiders keep
// killing enemy crystal workers. Built on DenaivamApex (center base and late spawning,
// center towers, raids, scout swarms).
// All-skills assault strategy + scout combat micro + energy gathering micro.
// Upload this one file as-is.

// =====================================================================
// BUILD ORDER — edit this.
// Items are bought top to bottom; `number` is how many of that item to buy.
// If an item only lacks energy, the bot saves up for it before buying anything later.
// If an item is impossible right now (not enough crystal, needs a second Base, unit
// cap, no free build site, too late in the game...), it is skipped and the next item is
// tried; the skipped item stays owed and is bought as soon as it becomes possible.
// Crystal items come first: as soon as the bank holds the crystal for an owed item
// (Soldier, Base, upgrades...), that item is bought before anything else in the list,
// and if it is then only short of energy the bot waits for the energy. While owed items
// wait for crystal, the bot spends only energy, so the crystal is kept for them.
// While everything left is blocked, and once the whole list has been bought, the bot
// decides what to build by itself (see FREE MODE below) until the game ends.
// Rules follow the arena README (README.md, rules 3.1.0): each upgrade is bought once per
// type and applies to every unit or wall of that type (`number` does not matter for them).
//
// Items:
//   "eWorker"           worker that gathers energy
//   "cWorker"           worker that gathers crystals
//   "WallWorker"        worker that walls off the enemy's crystals
//   "BarrierWorker"     an extra worker for the center wall (see BARRIER)
//   "Soldier"           fighter unit (needs 15 crystals)
//   "Scout"             scout; the bot gives it a job (crystal raid, crystal guard,
//                       energy raid, then base attack)
//   "CrystalRaiderScout" scout that raids crystals on the enemy side
//   "CrystalGuardScout" scout that guards crystals on our side
//   "EnergyRaiderScout" scout that hunts enemy energy workers
//   "BaseAttackScout"   scout that goes straight for enemy bases
//   "Tower"             defensive turret near our base
//   "OffensiveTower"    turret near the crystals (needs a second Base first)
//   "Base"              expansion base near the map center
//   "ScoutUpgrade"      the scout upgrade (15 C, bought once): every scout, now and later,
//                       gets speed 4 and 10 HP
//   "SoldierUpgrade"    the fighter upgrade (20 C, bought once): turrets ignore all our soldiers
//   "WallUpgrade"       the wall upgrade (50 E, bought once): every wall, now and later, 120 HP
// Item names are not case-sensitive. Unknown items are skipped (there is no cargo,
// attack or armor upgrade in the arena).
// =====================================================================
const BUILD_ORDER = [
  // One worker is moved onto the wall at tick 60 (BARRIER_WORKERS / BARRIER_START_TICK below).
  { item: "eWorker", number: 2 },
    { item: "cWorker", number: 2 },

  { item: "CrystalRaiderScout", number: 12 },
  { item: "defensiveTower", number: 1 },
  { item: "eWorker", number: 2 },
  { item: "BarrierWorker", number: 1 },
  { item: "CrystalRaiderScout", number: 10 },
    { item: "WallUpgrade", number: 1 },
  // Every crystal goes to soldiers; spare energy fills up with scouts that guard the center.
  { item: "Soldier", number: 20 },
  { item: "Scout", number: 20 },
]
// Build-order item name -> internal role used by the strategy code below.
const BUILD_ITEMS = {
  eworker: "eWorker", cworker: "cWorker",
  wallworker: "wallBuilderWorker", wallbuilderworker: "wallBuilderWorker",
  barrierworker: "barrierWorker", centerwallworker: "barrierWorker",
  soldier: "Soldier", fighter: "Soldier",
  scout: "Scout",
  crystalraiderscout: "cRaiderScout", craiderscout: "cRaiderScout",
  crystalguardscout: "cRaiderScoutHome", craiderscouthome: "cRaiderScoutHome",
  energyraiderscout: "eRaiderScout", eraiderscout: "eRaiderScout",
  baseattackscout: "baseAttackerScout", baseattackerscout: "baseAttackerScout",
  tower: "defensiveTower", defensivetower: "defensiveTower",
  offensivetower: "offensiveTower", centertower: "centerTower",
  base: "Base",
  scoutupgrade: "ScoutUpgrade", scoutspeedupgrade: "ScoutUpgrade",
  soldierupgrade: "SoldierUpgrade", fighterupgrade: "SoldierUpgrade",
  wallupgrade: "WallUpgrade",
};
// Jobs handed to generic "Scout" purchases, filled in this order; the rest guard the
// center crystals (cRaiderScoutHome).
const SCOUT_JOBS = [["cRaiderScout", 6]];

// FREE MODE (after the build order, or while everything left in it is blocked).
// Priorities: stop the enemy taking crystals, build soldiers, take over the center.
// Crystal-hunting scouts the bot keeps alive: [job, how many].
const FREE_MODE_CRYSTAL_SCOUTS = [["cRaiderScoutHome", 6], ["cRaiderScout", 4]];
const FREE_MODE_CENTER_TOWERS = 2;  // turrets over the center crystals (needs a second Base)
const FREE_MODE_PUSH_SOLDIERS = 99; // soldiers hold the center until there are this many,
                                    // then they march on the enemy base (99 = never)

// SOLDIER SWARMS: scouts gang up on a lonely enemy soldier (30 HP, kills a 5 HP scout per
// hit; an upgraded 10 HP scout survives one hit). Before attacking, the bot simulates the
// fight with the scouts it has nearby and the open tiles around the soldier, and only
// attacks if the soldier dies and we lose at most SWARM_MAX_LOSSES scouts.
// Rough guide: 8 plain scouts in the open lose 5; 6-8 upgraded scouts lose only 2-3.
const SWARM_ENABLED = true;
const SWARM_RADIUS = 12;        // scouts within this many tiles of the soldier can join
const SWARM_WITH_BASE_ATTACKERS = true; // base-attack scouts nearby join swarms too
const SWARM_MAX_LOSSES = 5;     // most scouts we accept losing for one soldier
const SWARM_LONELY_RADIUS = 4;  // "lonely": no other enemy soldier this close to it
const SWARM_TURRET_RADIUS = 5;  // ...and no enemy turret this close (turrets shred scouts)

// SPOTTER AND ENERGY RAID: one scout watches the enemy base area from outside turret
// range and records its defence (soldiers, turrets, scouts) and its energy workers.
// When our scouts can overwhelm that defence, ALL scouts raid the enemy energy nodes and
// kill every energy worker they find, then go back to their normal jobs.
// Overwhelm check: expected scout losses while killing the workers (soldiers kill about
// a scout per tick, turrets one every 2-3 ticks) must stay under RAID_MAX_LOSS_SHARE of
// our scouts. Upgraded scouts (10 HP) count as tougher.
const SPOTTER_ENABLED = false;     // off: CENTER GUARD keeps every scout at the center
const RAID_ENABLED = false;
const RAID_MIN_SCOUTS = 10;        // never raid with fewer scouts than this
const RAID_MAX_LOSS_SHARE = 0.4;   // raid only if we expect to lose at most 40% of them
const RAID_INTEL_TICKS = 40;       // how long a sighting near the enemy base stays valid
const RAID_ABORT_SHARE = 0.4;      // call the raid off below 40% of the starting scouts
const RAID_MAX_COVER = 1;          // raid workers covered by at most this many enemy turrets

// CENTER GUARD: every scout and soldier stays at the center and the wall. They fight
// anything that comes within CENTER_GUARD_RADIUS of the center (enemy crystal workers,
// enemies attacking the wall, raiders) but never go further out: no base attacks, no
// energy raids, no spotter, no soldier push. Idle units wait behind the wall. They also
// defend our own base area (CENTER_GUARD_HOME_RADIUS), never the enemy's.
// (Units spawned at our base walk to the center first.)
const CENTER_GUARD = true;
const CENTER_GUARD_RADIUS = 10;    // tiles from the map center (the wall is 4-7 out, the
                                   // crystals at most 7)
const CENTER_GUARD_HOME_RADIUS = 10; // units may also defend this far around our starting base
                                   // (its energy workers); 0 = center only. Tested: 10 wins
                                   // 106/116 (beats the old Bulwark 12/16); center only 100/116.

// SOLDIER MICRO: soldiers within 2 tiles of enemy units fight with soldierCombatMicro
// (soldier-combat-micro.js): focus fire, first strike on enemies walking in, dodge steps,
// badly hurt soldiers step out of reach, enemies at our base first. Tested: beats this bot
// without it 18/24 and DenaivamApex 21/24.
const SOLDIER_MICRO = true;

// AUTO UPGRADES (rules 3.1.0: each upgrade is bought once and covers every unit of its type):
// buy the scout upgrade (15 C: all scouts 10 HP, speed 4) once we have 3 scouts, and the
// fighter upgrade (20 C: turrets ignore all our soldiers) once enemy turrets show up while we
// have 2+ soldiers. Ahead of the build order. Set false to control them only from BUILD_ORDER.
const AUTO_UPGRADES = true;

// BARRIER: wall lines between the enemy and the map center.
// Each line is an arc of walls around the center (19.5,19.5), on the side facing the
// enemy base; our side stays open so our units walk in freely. Enemy units have to go
// around the ends, which keeps them further from the center and the crystals there.
// A finished line has no gaps (units move one tile up/down/left/right and cannot slip
// through). The innermost line goes first; then each next line one tile further out.
// Destroyed walls are rebuilt, inner line first. Once the inner line stands, spare energy
// upgrades the walls (per-unit rules: 50 E each, HP x2), most damaged first.
// Walls needed (roughly): 16 for the first line, 19 for the second, 23 for the third
// (3 E each). The zone hurts walls outside its circle in the last ~20 ticks.
const BARRIER_ENABLED = true;
const BARRIER_RADIUS = 4;          // the innermost line, in tiles from the map center
const BARRIER_LAYERS = 3;          // number of lines (each one tile further out)
const BARRIER_ARC = 100;           // how far the arc reaches around, in degrees either side of
                                   // the enemy's direction (90 = half a ring; 180 = full ring,
                                   // which also closes our side)
const BARRIER_WORKERS = 1;         // workers the bot keeps on the wall, taken from the starting
                                   // workers at BARRIER_START_TICK ("BarrierWorker" items add more)
const BARRIER_START_TICK = 60;    // when the wall worker is taken. Tested: tick 0 (or 30) costs one of
                                   // the only two starting energy workers and loses far more games
                                   // (5/32 vs 17/32 against DenaivamApex + DenaivamMaikaTi); 60 is best.
const BARRIER_MAX_LOST = 3;        // replace a killed wall worker at most this often
const BARRIER_UPGRADE_RESERVE = 60; // energy kept for units before upgrading walls
const LATE_SPAWN = true;           // a base near the center spawns until the end (its units
                                   // stand in the final circle and count at tick 500)
const ENDGAME_BASE_TICK = 180;     // from here a base near the center goes first

// APEX: center towers from surplus energy. When the unit cap is reached or energy piles up
// (otherwise wasted), turrets go up around our base near the center, CENTER_TOWER_MIN..MAX
// tiles from the map center: just outside the final circle (they take none of the 32 safe
// tiles) yet close enough to survive the zone (50 HP, at most 24 damage there). In the
// end-game brawl they hit enemy units in the circle for 4 damage per tick.
const CENTER_TOWERS = 4;              // most center towers
const CENTER_TOWER_ENERGY = 150;      // build them when energy reaches this, or at the unit cap
const CENTER_DENIAL = true;           // crystal hunters also kill enemy workers building in the center
const CENTER_TOWER_MIN_RADIUS = 3.3;
const CENTER_TOWER_MAX_RADIUS = 4.6;
// RUSH DEFENCE: an early enemy army at our base (scout rushes surround the base, block
// deposits and spawns, and kill it before tick 100) gets a turret beside the base ahead of
// everything else; while the turret only lacks energy, nothing else is bought.
// A turret kills a 5 HP scout every 2 ticks, so one in time saves the 200 HP base.
const RUSH_DEFENCE = true;
const RUSH_MIN_ENEMIES = 3;   // enemy scouts/soldiers within RUSH_RADIUS of one of our bases
const RUSH_RADIUS = 14;       // before RUSH_EARLY_TICK: seen this far out (a surrounded base gets
const RUSH_EARLY_TICK = 60;   // no deposits, so a rush must be seen coming); later only enemies
const RUSH_BASE_RADIUS = 3;   // this close to a base count (normal raids are not rushes)
const RUSH_ALERT_TICKS = 40;  // the alert (and the saving for the turret) lasts this long
const RUSH_MAX_TURRETS = 2;   // one turret per 5 attackers, at most this many
const RUSH_UNTIL_TICK = 250;  // only early in the game
